export type Options<TData extends TDataShape = TDataShape, ThrowOnError extends boolean = boolean, TResponse = unknown> = Options2<TData, ThrowOnError, TResponse> & {
    /**
     * You can provide a client instance returned by `createClient()` instead of
     * individual options. This might be also useful if you want to implement a
     * custom client.
     */
    client?: Client;
    /**
     * You can pass arbitrary values through the `meta` object. This can be
     * used to access values that aren't defined as part of the SDK function.
     */
    meta?: keyof ClientMeta extends never ? Record<string, unknown> : ClientMeta;
};

/**
 * Authenticate with Auth0
 *
 * Authenticate a user via Auth0 Single Sign-On (SSO).
 * This endpoint verifies an Auth0 JWT token and creates or updates the user session in Storyblok.
 *
 * The token should be a valid Auth0 JWT obtained from the Auth0 authentication flow.
 * The endpoint matches the user’s organization by email domain, and it automatically
 * provisions or merges user accounts based on the organization’s settings.
 *
 */
export const authenticateAuth0 = <ThrowOnError extends boolean = false>(options: Options<AuthenticateAuth0Data, ThrowOnError>): RequestResult<AuthenticateAuth0Responses, unknown, ThrowOnError> => (options.client ?? client).get<AuthenticateAuth0Responses, unknown, ThrowOnError>({ url: '/v1/auth0', ...options });

/**
 * Check FlowMotion access
 *
 * Returns whether the current user has active FlowMotion access.
 * Requires the user to have an organization with FlowMotion configured.
 */
export const checkFlowMotionAccess = <ThrowOnError extends boolean = false>(options?: Options<CheckFlowMotionAccessData, ThrowOnError>): RequestResult<CheckFlowMotionAccessResponses, CheckFlowMotionAccessErrors, ThrowOnError> => (options?.client ?? client).get<CheckFlowMotionAccessResponses, CheckFlowMotionAccessErrors, ThrowOnError>({
    security: [{ name: 'authorization', type: 'apiKey' }, { scheme: 'bearer', type: 'http' }],
    url: '/v1/auth/flow_motion',
    ...options
});

/**
 * Authenticate with FlowMotion
 *
 * Provisions and authenticates a user with FlowMotion (n8n).
 * Requires the user to have an organization with FlowMotion configured.
 */
export const authenticateFlowMotion = <ThrowOnError extends boolean = false>(options?: Options<AuthenticateFlowMotionData, ThrowOnError>): RequestResult<AuthenticateFlowMotionResponses, AuthenticateFlowMotionErrors, ThrowOnError> => (options?.client ?? client).post<AuthenticateFlowMotionResponses, AuthenticateFlowMotionErrors, ThrowOnError>({
    security: [{ name: 'authorization', type: 'apiKey' }, { scheme: 'bearer', type: 'http' }],
    url: '/v1/auth/flow_motion',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options?.headers
    }
});

/**
 * Get GitHub OAuth URL
 *
 * Returns the GitHub OAuth authorization URL that the client should redirect the user to.
 * The user authenticates with GitHub, and GitHub redirects them back with an authorization code.
 *
 */
export const getGithubOauthUrl = <ThrowOnError extends boolean = false>(options?: Options<GetGithubOauthUrlData, ThrowOnError>): RequestResult<GetGithubOauthUrlResponses, unknown, ThrowOnError> => (options?.client ?? client).get<GetGithubOauthUrlResponses, unknown, ThrowOnError>({ url: '/v1/auth/github/oauth_url', ...options });

/**
 * Authenticate with GitHub
 *
 * Authenticate a user via GitHub OAuth. Exchanges the GitHub authorization code for user information,
 * then creates or updates the user session. If the user doesn’t exist, the API creates a new account.
 * Optional `rid` applies a pending invitation (collaborator, org, or partner) in the same request.
 *
 */
export const authenticateGithub = <ThrowOnError extends boolean = false>(options: Options<AuthenticateGithubData, ThrowOnError>): RequestResult<AuthenticateGithubResponses, AuthenticateGithubErrors, ThrowOnError> => (options.client ?? client).post<AuthenticateGithubResponses, AuthenticateGithubErrors, ThrowOnError>({
    url: '/v1/auth/github',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * GitHub
 *
 * Use this endpoint to obtain details of the GitHub account connected to Storyblok.
 */
export const getGithubStatus = <ThrowOnError extends boolean = false>(options?: Options<GetGithubStatusData, ThrowOnError>): RequestResult<GetGithubStatusResponses, GetGithubStatusErrors, ThrowOnError> => (options?.client ?? client).get<GetGithubStatusResponses, GetGithubStatusErrors, ThrowOnError>({
    security: [{ name: 'authorization', type: 'apiKey' }, { scheme: 'bearer', type: 'http' }],
    url: '/v1/auth/github/me',
    ...options
});

/**
 * Connect GitHub account
 *
 * Connects the authenticated user’s Storyblok account to a GitHub account.
 * Exchanges the GitHub authorization code for user information and creates the identity link.
 * Fails if the user already has a GitHub account linked or if another user already linked the GitHub account.
 *
 */
export const connectGithub = <ThrowOnError extends boolean = false>(options: Options<ConnectGithubData, ThrowOnError>): RequestResult<ConnectGithubResponses, ConnectGithubErrors, ThrowOnError> => (options.client ?? client).post<ConnectGithubResponses, ConnectGithubErrors, ThrowOnError>({
    security: [{ name: 'authorization', type: 'apiKey' }, { scheme: 'bearer', type: 'http' }],
    url: '/v1/auth/github/connect',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Disconnect GitHub account
 *
 * Disconnects the authenticated user’s GitHub account from their Storyblok account.
 * Revokes the GitHub OAuth authorization and removes the identity link.
 *
 */
export const disconnectGithub = <ThrowOnError extends boolean = false>(options?: Options<DisconnectGithubData, ThrowOnError>): RequestResult<DisconnectGithubResponses, DisconnectGithubErrors, ThrowOnError> => (options?.client ?? client).post<DisconnectGithubResponses, DisconnectGithubErrors, ThrowOnError>({
    security: [{ name: 'authorization', type: 'apiKey' }, { scheme: 'bearer', type: 'http' }],
    url: '/v1/auth/github/disconnect',
    ...options
});

